#: The tools blocks: the freezes their judged runs ran under, the rounds as scripts/tools_block.py
#: names them, and their tools. The plan version is read from each freeze's own source, and the
#: date and the pair from the folder of the block's first round.
TOOLS_BLOCKS = (
    ((21, 22), "ROUNDS", ("valkey-benchmark", "memtier_benchmark", "wrk2", "vegeta", "hey", "k6",
                          "kafka-producer-perf", "kafka-end-to-end", "rabbitmq-perftest",
                          "nats-latency", "rdkafka_performance")),
    ((30,), "ROUNDS_V33", ("omb", "pulsar-perf", "emqtt-bench", "ycsb", "nats-bench")),
    ((32,), "ROUNDS_V35", ("xinfra-monitor", "strimzi-canary", "trogdor", "stream-perftest")),
    ((33,), "ROUNDS_V36", ("ysb",)),
    ((34,), "ROUNDS_V37", ("pkb",)),
    ((35,), "ROUNDS_V38", ("mqtt-benchmark", "sarama-producer-perf", "sbk", "kgo-repeater")),
    ((36,), "ROUNDS_V39", ("artemis-perf", "rocketmq-benchmark", "bookkeeper-benchmark")),
    ((37,), "ROUNDS_V40", ("quiver", "pravega-benchmark")),
    ((38,), "ROUNDS_V41", ("pubsub-loadtest",)),
)
FREEZES_DIR = "freezes"
MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


def _plan_version(freeze, root=FREEZES_DIR):
    """The plan version a freeze holds, from the first "Version N" of its own source."""
    import re as _re
    path = os.path.join(root, "%02d-experiment-plan" % freeze, "experiment_plan.tex")
    with open(path, encoding="utf-8") as fh:
        found = _re.search(r"Version (\d+)", fh.read())
    if not found:
        raise ValueError("%s names no plan version" % path)
    return int(found.group(1))


def tools_blocks(root=FREEZES_DIR):
    """[{"freezes", "plans", "date", "pair", "tools"}] for each tools block, checked.

    The plan in a folder named vNN_... must be the version the block's freeze holds, so a freeze
    number typed wrong here stops the table; a block of the first pair's folders that is not
    on the second (../matched-b/) is on the first.
    """
    import re as _re
    import tools_block
    out = []
    for freezes, rounds, tools in TOOLS_BLOCKS:
        folder = getattr(tools_block, rounds)[0][1]
        plans = tuple(_plan_version(f, root) for f in freezes)
        named = _re.search(r"(?:^|/)v(\d+)_", folder)
        if named and int(named.group(1)) != plans[-1]:
            raise ValueError("%s's folder %s is plan version %s; freeze %d holds version %d"
                             % (rounds, folder, named.group(1), freezes[-1], plans[-1]))
        day = _re.search(r"_(\d{4})(\d{2})(\d{2})T", folder)
        out.append({"freezes": freezes, "plans": plans,
                    "date": "%d %s" % (int(day.group(3)), MONTHS[int(day.group(2)) - 1]),
                    "pair": "second" if folder.startswith("../matched-b/") else "first",
                    "tools": tools})
    return out


#: The table of tools run lists the intervals from the most separated to the least, the order of
#: the paper's Table III: two hosts, two processes, two processes on one host, one process, a
#: publish to its acknowledgment, a round trip.
TOOLS_TABLE_ORDER = tuple(reversed(TRIP_ORDER))

#: The registry's responses in the short words the table of tools run prints, its caption
#: spelling each out; one for every response the registry's own table labels.
TOOLS_TABLE_LABELS = {
    "positive_only_filter": "filter $>0$",
    "nonnegative_filter": "filter $" + chr(92) + "geq 0$",
    "silent_suppression": "substitute",
    "library_refusal": "refuse",
    "quantized_retention": "truncate",
}

#: S1's tools by the names the tools blocks give them: S1 ran Stream PerfTest as one instance,
#: where its block ran it as two (freeze 34, D37-4).
S1_TOOLS_RUN = {"stream-perftest-one": "stream-perftest"}


def _tools_run_cells(v):
    """A tool run's "At or below zero" and "Counted" cells from its registry fold: the cells
    `_registry_cells` gives the registry's own table, in the short words of TOOLS_TABLE_LABELS
    and with two responses joined on one line, so the table fits the page."""
    if set(TOOLS_TABLE_LABELS) != set(REGISTRY_LABELS):
        raise ValueError("the table of tools run has short words for %s; the registry's table "
                         "labels %s" % (sorted(TOOLS_TABLE_LABELS), sorted(REGISTRY_LABELS)))
    kinds = sorted(v["kinds"] & set(TOOLS_TABLE_LABELS))
    if kinds:
        return ("; ".join(TOOLS_TABLE_LABELS[k] for k in kinds),
                "yes" if v["counts_discards"] else "no")
    if v["counts_discards"]:
        return "discard", "yes"
    if v.get("tally_guard"):
        return "zero in average", "no"
    return "---", "---"


def _s1_held(csv_path=S1_CSV, verdicts_path=S1_VERDICTS, more=S1_MORE):
    """{tool run: (rounds its S1 prediction held, rounds judged)}, by the tools blocks' names,
    read once `_s1` has checked the same files against the prose."""
    _s1(csv_path, verdicts_path, more)
    held = {}
    for _rows, judged in ((csv_path, verdicts_path),) + tuple(more):
        with open(judged, encoding="utf-8") as fh:
            for tool, v in json.load(fh).items():
                rounds = len(v["held_in_rounds"])
                held[S1_TOOLS_RUN.get(tool, tool)] = (rounds,
                                                      rounds + len(v["failed_in_rounds"]))
    return held


def _sort_name(tool):
    """A tool's name as a reader alphabetizes it, Kafka's macro read as the word."""
    return TOOL_NAMES[tool].replace("\\kafka{}", "Kafka").lower()


def render_tools_table(t1_path=TOOLS_T1, t2_path=TOOLS_T2, root=FREEZES_DIR, s1=None):
    """Supplement S5's table of every tool run, one row each.

    15 Oct 2026, at referee A's 9.7 and B's U5: two tables became this one. The first gave what
    a tool times, how its figure followed the delay (T1) and how many clocks T2 found its two
    timestamps on; the second what the reading at source found it does with a value at or below
    zero, and the freeze, plan version, day and pair of the block that ran it. A tool's author
    now finds all of it in one row, with S1's rounds beside it.

    The slope is per crossing, the least and greatest over the rounds, and --- where the tool
    timed a managed service, which the staircase cannot reach (D37-1, D41-3). Runs counts the T2
    runs answered as the clocks named (D34-2), of all that tool's T2 runs, the rest undecided
    (`_tools_judged` has refused anything else). Artemis's perf client spans two processes but
    its figures cannot show the offset (CLOCKS_NOT_PREDICTED), and the Pub/Sub load test prints
    none under it (CLOCKS_UNANSWERED): each is listed as two, with none so answered. The Pravega
    benchmark times within one process and is listed as one, beside what its count let the rule
    answer (CLOCKS_BY_COUNT). S1 counts the rounds its prediction held, of those judged, and ---
    where the tool did not run it. Both tables' guards stand: the tools block's
    (`_tools_judged`), one block for each tool and a freeze typed wrong stopping the table
    (`tools_blocks`), the registry's, and S1's (`_s1`).
    """
    import harness_registry
    t1, t2 = _tools_rows(t1_path, t2_path)
    _tools_judged(t1, t2)
    trip = {r["tool"]: r["trip"] for r in t1}
    blocks = tools_blocks(root)
    listed = [t for b in blocks for t in b["tools"]]
    if sorted(listed) != sorted(trip) or len(set(listed)) != len(listed):
        raise ValueError("the tools blocks list %s; the tools run are %s"
                         % (sorted(listed), sorted(trip)))
    if set(TOOL_REGISTRY_PATHS) != set(trip):
        raise ValueError("TOOL_REGISTRY_PATHS maps %s; the tools run are %s"
                         % (sorted(TOOL_REGISTRY_PATHS), sorted(trip)))
    folded = harness_registry.paths()
    unheld = sorted(t for t, where in TOOL_REGISTRY_PATHS.items()
                    if where is not None and where not in folded)
    if unheld:
        raise ValueError("TOOL_REGISTRY_PATHS sends %s to spans the registry does not hold"
                         % unheld)
    held = _s1_held() if s1 is None else s1
    if set(held) - set(trip):
        raise ValueError("S1 judged %s, which no tools block ran" % sorted(set(held) - set(trip)))
    block = {t: b for b in blocks for t in b["tools"]}
    lines = ["% Generated by scripts/emit_paper_numbers.py from docs/results/tools/tools_t1.csv,",
             "% tools_t2.csv, the S1 verdicts, docs/results/external/harness_registry.csv and the",
             "% freezes. Do not edit by hand.",
             "\\begin{tabular}{@{}llllllrrlll@{}}",
             "\\toprule",
             " & & At or & & T1 & \\multicolumn{2}{c}{T2} & S1 & Freeze & & \\\\",
             "\\cmidrule(lr){6-7}",
             "Tool & Interval & below zero & Counted & slope & Clocks & Runs & held & (plan) & "
             "Began & Pair \\\\",
             "\\midrule"]
    for tool in sorted(trip, key=lambda t: (TOOLS_TABLE_ORDER.index(trip[t]), _sort_name(t))):
        where = TOOL_REGISTRY_PATHS[tool]
        disposal, counted = (("not read", "---") if where is None
                             else _tools_run_cells(folded[where]))
        slopes = [float(r["slope"]) / int(r["crossings"])
                  for r in t1 if r["tool"] == tool and r["slope"]]
        slope = "%s--%s" % (_signed(min(slopes)), _signed(max(slopes))) if slopes else "---"
        runs = [r for r in t2 if r["tool"] == tool]
        label = "two" if trip[tool] in TWO_CLOCK_TRIPS else "one"
        b = block[tool]
        lines.append("%s & %s & %s & %s & %s & %s & %d/%d & %s & %s (%s) & %s & %s \\\\" % (
            TOOL_NAMES[tool], TRIP_CELLS[trip[tool]], disposal, counted, slope, label,
            sum(r["clocks"] == label for r in runs), len(runs),
            "%d/%d" % held[tool] if tool in held else "---",
            "--".join(str(f) for f in b["freezes"]), "--".join(str(p) for p in b["plans"]),
            b["date"], b["pair"]))
    lines += ["\\bottomrule", "\\end{tabular}", ""]
    return "\n".join(lines)


def draft_v10_macros():
    """Every macro of the revised draft's that this module adds on 15 Oct 2026, in one list."""
    return (audit_step_macros() + law_free_slope_macros() + ack_past_one_macros()
            + module_cost_macros() + fix_interval_macros() + rt_floor_macros()
            + colocated_macros() + redis_floor_macros())


