def _all_pairs(m):
    return (list(macros(m)) + span_macros() + stat_macros() + grid_macros()
            + retention_macros() + traced_macros() + tost_macros() + tti_tost_macros()
            + first_result_macros() + occupancy_fall_macros()
            + stall_robustness_macros()
            + mechanism_macros() + kernel_macros() + registry_macros()
      + novelty_macros()
            + registry_sources_macro()
            + clocksource_macros() + traced_ratio_macros() + audit_macros()
            + priority_macros() + priority_residual_macros() + fork_macros()
            + chrony_bound_macros() + disease_macros()
            + exposure_macros() + exposure_side_macros() + artifact_macros()
            + separability_macros()
            + h3_stamping_macros()
            + paired_gap_macros() + handling_share_macros() + inter_host_offset_macros()
            + spread_macros() + payload_flip_macros() + literature_census_macros()
            + arm_macros() + manipulation_macros()
            + deletion_macros() + literature_macros() + cliff_macros() + reach_macros()
            + tools_block_macros() + tools_load_macros() + ysb_flush_macros() + ysb_fit_macros()
            + k1_macros() + s1_macros() + brokers_block_macros() + quiver_block_macros()
            + pravega_count_macros() + pubsub_block_macros()
            + recv_wait_macros() + full_fix_macros() + so_fix_macros()
            + law_reading_macros()
            + s_window_macros() + s_rate_macros() + rate_by_delivery_macros()
            + mechanism_interval_macros()
            + traced_pooled_macros() + workload_macros() + backlog_macros()
            + cell_events_macros() + tracer_macros() + geometry_seven_macros()
            # 15 Oct 2026, the referees' reports of that day: the trace check at four
            # thresholds and each broker's margin, and the per-run rates by broker.
            + trace_threshold_macros() + run_rate_macros() + run_level_macros()
            # 15 Oct 2026: the macros the revised draft reads that nothing emitted yet, and
            # freeze 41's, read through its own judges.
            + draft_v10_macros() + order_scope_macros())


def render(m):
    body = "".join("\\newcommand{\\%s}{%s}\n" % (name, val) for name, val in all_pairs(m))
    return HEADER + body


def main(argv=None):
    ap = argparse.ArgumentParser(description="Emit campaign numbers as LaTeX macros")
    ap.add_argument("--ledger", default=os.path.join("docs", "results",
                                                     "external_campaigns_index.csv"))
    ap.add_argument("--out", default=DEFAULT_OUT)
    ap.add_argument("--table", default=DEFAULT_TABLE)
    ap.add_argument("--registry-table", default=DEFAULT_REGISTRY_TABLE)
    ap.add_argument("--priority-table", default=DEFAULT_PRIORITY_TABLE)
    ap.add_argument("--exposure-table", default=DEFAULT_EXPOSURE_TABLE)
    ap.add_argument("--spread-table", default=DEFAULT_SPREAD_TABLE)
    ap.add_argument("--interval-table", default=DEFAULT_INTERVAL_TABLE)
    ap.add_argument("--tools-table", default=DEFAULT_TOOLS_TABLE)
    ap.add_argument("--tools-load-table", default=DEFAULT_TOOLS_T3_TABLE)
    ap.add_argument("--k1-table", default=DEFAULT_K1_TABLE)
    ap.add_argument("--s1-table", default=DEFAULT_S1_TABLE)
    ap.add_argument("--recv-wait-table", default=DEFAULT_RECV_WAIT_TABLE)
    ap.add_argument("--full-fix-table", default=DEFAULT_FULL_FIX_TABLE)
    ap.add_argument("--so-fix-table", default=DEFAULT_SO_FIX_TABLE)
    ap.add_argument("--mechanism-table", default=DEFAULT_MECHANISM_TABLE)
    ap.add_argument("--groups-table", default=DEFAULT_GROUPS_TABLE)
    ap.add_argument("--geometry-table", default=DEFAULT_GEOMETRY_TABLE)
    ap.add_argument("--payload-table", default=DEFAULT_PAYLOAD_TABLE)
    ap.add_argument("--tracer-table", default=DEFAULT_TRACER_TABLE)
    ap.add_argument("--trace-table", default=DEFAULT_TRACE_TABLE)
    ap.add_argument("--gap-table", default=DEFAULT_GAP_TABLE)
    ap.add_argument("--spans-table", default=DEFAULT_SPANS_TABLE)
    ap.add_argument("--audit-sensitivity-table", default=DEFAULT_AUDIT_SENSITIVITY_TABLE)
    ap.add_argument("--order-scope-table", default=DEFAULT_ORDER_SCOPE_TABLE)
    ap.add_argument("--check", action="store_true",
                    help="fail if the committed file disagrees with the ledger; write nothing")
    args = ap.parse_args(argv)

    if not os.path.exists(args.ledger):
        print("missing: %s" % args.ledger)
        return 1
    cells = load_cells(args.ledger)
    if not cells:
        print("no admissible cells in %s -- refusing to emit numbers from nothing" % args.ledger)
        return 1

    m = measured(cells)
    # Both generated files are gated together. The grid table was the one place a number
    # reached the page without passing through this script, and it is the one place the
    # paper contradicted its own caption.
    targets = [(args.out, render(m))]
    try:
        targets.append((args.table, render_grid_table()))
    except (ImportError, OSError, KeyError, ValueError) as exc:
        print("note: grid table not generated (%s)" % exc)
    reg = render_registry_table()
    if reg:
        targets.append((args.registry_table, reg))
    try:
        targets.append((args.priority_table, render_priority_table()))
        targets.append((args.exposure_table, render_exposure_table()))
        targets.append((args.spread_table, render_spread_table()))
        targets.append((args.interval_table, render_interval_table()))
    except (ImportError, OSError, KeyError, ValueError) as exc:
        print("note: priority table not generated (%s)" % exc)
    # The tools block's table is not caught like the four above: its guards are the reason it
    # exists, and a guard that tripped into a "note:" would leave the committed table standing
    # beside data that no longer supports it. Only its absence is tolerated. Since 15 Oct 2026
    # it carries each tool's S1 rounds too, so it needs S1's verdicts beside the two tables.
    if all(os.path.exists(p) for p in (TOOLS_T1, TOOLS_T2, S1_CSV, S1_VERDICTS)):
        targets.append((args.tools_table, render_tools_table()))
    if os.path.exists(TOOLS_T3):
        targets.append((args.tools_load_table, render_tools_load_table()))
    # K1 like the tools block: its guard is why the table exists, so only its absence is tolerated.
    if os.path.exists(K1_CSV) and os.path.exists(K1_VERDICTS):
        targets.append((args.k1_table, render_k1_table()))
    # S1 the same way (freeze 34).
    if os.path.exists(S1_CSV) and os.path.exists(S1_VERDICTS):
        targets.append((args.s1_table, render_s1_table()))
    recv = render_recv_wait_table()
    if recv:
        targets.append((args.recv_wait_table, recv))
    fix = render_full_fix_table()
    if fix:
        targets.append((args.full_fix_table, fix))
    sockets = render_so_fix_table()
    if sockets:
        targets.append((args.so_fix_table, sockets))
    if os.path.exists(MECH_INTERVALS_CSV):
        targets.append((args.mechanism_table, render_mechanism_table()))
    if os.path.exists(GROUPS_CSV):
        targets.append((args.groups_table, render_groups_table()))
    # 7 Oct 2026: typed by hand until the late messages were left out; generated since, so
    # that the next recount moves them with everything else.
    if all(os.path.exists(os.path.join("docs", "results", "model", p, "knee_resolution.csv"))
           for p in GEOMETRY_PHASES):
        targets.append((args.geometry_table, render_geometry_table()))
    if all(os.path.exists(p) for p in PAYLOAD_SWEEPS):
        targets.append((args.payload_table, render_payload_table()))
    if os.path.exists(MECH_INTERVALS_CSV) and os.path.exists(UNTRACED_CSV) \
            and all(os.path.exists(f) for f, _ in TRACED_FILES):
        targets.append((args.tracer_table, render_tracer_table()))
    # 15 Oct 2026: three tables the referees asked for, which the text takes up in the same
    # revision -- the trace check's thresholds and margins, the gap distortion's matched
    # workloads, and Table I with each span's smallest value.
    if trace_threshold_macros():
        targets.append((args.trace_table, render_trace_threshold_table()))
    if gap_pairs():
        targets.append((args.gap_table, render_gap_table()))
    if os.path.exists(SPAN_CSV):
        targets.append((args.spans_table, render_spans_table()))
    # 15 Oct 2026, the revised draft: Supplement S5's table of the audit's count under each of
    # its readings. Its table of every tool run is the tools table above.
    if os.path.exists(AUDIT_SENSITIVITY_CSV):
        targets.append((args.audit_sensitivity_table, render_audit_sensitivity_table()))
    # 15 Oct 2026: freeze 41's verdicts, Supplement S3.11, once every block is committed.
    scope = render_order_scope_table()
    if scope:
        targets.append((args.order_scope_table, scope))

    if args.check:
        stale = False
        for path, want in targets:
            if not os.path.exists(path):
                print("missing: %s (run without --check to create it)" % path)
                stale = True
                continue
            with open(path, encoding="utf-8") as fh:
                have = fh.read()
            if have.replace("\r\n", "\n") != want:
                print("STALE: %s disagrees with the artefacts" % path)
                stale = True
        if stale:
            print("  regenerate with: python scripts/emit_paper_numbers.py")
            return 1
        print("OK: %s generated file(s) match the artefacts" % len(targets))
        return 0

    for path, want in targets:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(want)
        print("wrote %s" % path)
    for name, val in all_pairs(m):
        print("  \\%-22s %s" % (name, val))
    return 0


if __name__ == "__main__":  # pragma: no cover - dispatch only; main() is tested directly
    sys.exit(main())
